script:
//https://erp.dinord.ru/app/issue/ISS-2025-01455
//https://community.softr.io/t/new-custom-code-display-two-blocks-next-to-each-other-with-a-drag-border-feature/2555

var task_tree_layout_styles = `
    .column {
      float: left;
      z-index: 1;
    }

    .left-column {
      width: 95%;
      position: relative;
    }

    .right-column {
      width: 5%;
      position: relative;
    }

    .draggable-border {
      position: absolute;
      top: 0;
      width: 2px;
      height: 100%;
      cursor: col-resize;
      z-index: 10;
      background-color: #ebebeb;
      border-radius: 4px;
    }

    .left-column .draggable-border {
      right: -1px;
    }

    .right-column .draggable-border {
      left: -1px;
    }

    .draggable-border:hover {
        background-color: var(--bg-dark-gray);
    }

    .row:after {
      content: "";
      display: table;
      clear: both;
    }

    @media screen and (max-width: 600px) {
      .column {
        width: 100%;
      }
    }

    .draggable-border:after {
        content: "⁝⁝";
        position: absolute;
        transition: border-color .6s ease-out;
        top: calc(50% - 8.5px);
        font-size: 15px;
        background-color: #ebebeb;
        color: black;
        border-radius: 2px;
        right: -3px;
    }

    [data-theme="dark"] {
        & .draggable-border
        & .draggable-border:after {
            background-color: #b1b1b1;
        }
    }
`;
var task_tree_layout_styles_element = document.createElement("style");
task_tree_layout_styles_element.textContent = task_tree_layout_styles;
document.head.appendChild( task_tree_layout_styles_element );

const layout_block = $(`<div class="row">
  <div class="column left-column">
    <div class="draggable-border"></div>
    <span id="tocolumn1"></span>
  </div>
  <div class="column right-column">
    <div class="draggable-border"></div>
    <span id="tocolumn2"></span>
    <div id="task-gantt"></div>
  </div>
</div>`);

function setup_task_tree_layout() {
    var dragging = false;
    var leftColumn = $('.left-column');
    var rightColumn = $('.right-column');
    var border = $('.draggable-border');

    border.mousedown(function(e) {
        e.preventDefault();
        dragging = true;
    });

    $(document).mouseup(function() {
        dragging = false;
    });

    $(document).mousemove(function(e) {
        if (dragging) {
            var offset = e.pageX - leftColumn.offset().left;
            var newLeftWidth = offset / leftColumn.parent().width() * 100;
            var newRightWidth = 100 - newLeftWidth;

            if (newLeftWidth < 30) {
            } else if (newRightWidth < 2) {
            } else {
                leftColumn.css('width', newLeftWidth + '%');
                rightColumn.css('width', newRightWidth + '%');
                localStorage.setItem(`layout_widths_${cur_tree.view_name}_${cur_tree.args.doctype}`, newLeftWidth );
            }
        }
    });
};

function _set_initial_layout_width( layout_block ) {
    let leftWidth = localStorage.getItem(`layout_widths_${cur_tree.view_name}_${cur_tree.args.doctype}`);

    if ( leftWidth ) {
        var rightWidth = 100 - leftWidth;
        $('.left-column').css('width', leftWidth + '%');;
        $('.right-column').css('width', rightWidth + '%');
    }
    let is_xl = $(document).width() > 1400; 
    let is_fw = $(document.body).hasClass( "full-width" );
    if ( (is_xl && !is_fw) || (!is_xl && is_fw) ) {
        frappe.ui.toolbar.toggle_full_width();
    }
}

function build_task_tree_layout( treeview ) {
    layout_block.insertAfter("#page-Tree\\/Task div.page-form.row");
    _set_initial_layout_width( layout_block );

    $(".tree-table").insertAfter($("#tocolumn1"));
    $(".tree-header").insertAfter($("#tocolumn1"));

    setup_task_tree_layout();
}
